const ARRIVAL_STATEMENTS: Record<string, { kind: "log" | "set"; add_sql: string; del_sql: string | null }> = {
  head: { kind: "set", add_sql: `INSERT INTO "head" ("_repo_id", "rev_id") VALUES (?, ?) ON CONFLICT ("_repo_id") DO UPDATE SET "rev_id" = excluded."rev_id"`, del_sql: `DELETE FROM "head" WHERE "_repo_id" = ? AND "rev_id" = ?` },
  tree_file: { kind: "set", add_sql: `INSERT INTO "tree_file" ("rev_id", "path", "tree_digest") VALUES (?, ?, ?) ON CONFLICT ("rev_id", "path") DO UPDATE SET "tree_digest" = excluded."tree_digest"`, del_sql: `DELETE FROM "tree_file" WHERE "rev_id" = ? AND "path" = ? AND "tree_digest" = ?` },
  worktree_edit: { kind: "log", add_sql: `INSERT INTO "worktree_edit" ("path", "digest") VALUES (?, ?)`, del_sql: null },
};

function arrival_statement(arrival: IArrivalRow): SqlStatement {
  const template = ARRIVAL_STATEMENTS[arrival.rel];
  if (template === undefined) {
    throw new Error(`dirty_derives_from_digest_mismatch: tick received an arrival for undeclared rel '${arrival.rel}'`);
  }
  if (arrival.sign === "del") {
    if (template.kind === "log") {
      throw new Error(`dirty_derives_from_digest_mismatch: retract from log rel '${arrival.rel}' (engine.pl retract_from_log)`);
    }
    if (template.del_sql === null) {
      throw new Error(`dirty_derives_from_digest_mismatch: rel '${arrival.rel}' has no delete statement`);
    }
    return { sql: template.del_sql, args: bind_args(arrival.row) };
  }
  return { sql: template.add_sql, args: bind_args(arrival.row) };
}

function apply_arrivals(seam: ISqlSeam, arrivals: IArrivalBatch): Observable<unknown> {
  const statements: SqlStatement[] = arrivals.map(arrival_statement);
  return seam.runner.batch(seam.db, statements);
}

